// MySpace\MyS_Front\src\paginas\logeo\Registro.jsx

// YA ES FUNCIONAL - MODIFICADO PARA USAR DATOS DE EJEMPLO

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Registro.css";
import { registro } from "../../Api";

// importe de la base
import Base_Main from "../../bases/Base_Main";

// **IMPORTACIÓN DE DATOS DE PERFIL**
import perfilData from "../../data/perfilData";

// Extraer el primer perfil para inicializar
const initialUserData = perfilData[0] || {};
// Los datos de ejemplo no tienen Apellidos ni Fecha de Nacimiento.
// Si los tuvieran, se extraen aquí. Usamos valores por defecto si no existen.
const initialNombre = initialUserData.nombre || "";
const initialCorreo = initialUserData.correo || "";
const initialPass = initialUserData.password || "";
const initialApPaterno = ""; // El dato no está en el ejemplo, se inicializa vacío
const initialApMaterno = ""; // El dato no está en el ejemplo, se inicializa vacío
const initialFechaNacimiento = ""; // El dato no está en el ejemplo, se inicializa vacío


export default function Registro() {

  const navigate = useNavigate();

  // Estados inicializados con los datos de ejemplo
  const [nombre, setNombre] = useState(initialNombre);
  const [apPaterno, setApPaterno] = useState(initialApPaterno);
  const [apMaterno, setApMaterno] = useState(initialApMaterno);
  const [correo, setCorreo] = useState(initialCorreo);
  const [pass1, setPass1] = useState(initialPass);
  const [pass2, setPass2] = useState(initialPass); // Inicializar pass2 igual a pass1
  const [fechaNacimiento, setFechaNacimiento] = useState(initialFechaNacimiento);
  const [loading, setLoading] = useState(false);

  const registrarUsuario = async (e) => {

    e.preventDefault();

    console.log("=== INICIO REGISTRO ===");

    // Validar contraseñas
    if (pass1 !== pass2) {
      alert("Las contraseñas no coinciden");
      return;
    }

    if (pass1.length < 6) {
      alert("La contraseña debe tener al menos 6 caracteres");
      return;
    }

    if (!fechaNacimiento) {
      alert("Por favor ingresa tu fecha de nacimiento");
      return;
    }

    setLoading(true);

    try {
      // Preparar datos para enviar al backend
      // NOTA: Para un registro REAL, el usuario debería ingresar sus propios datos.
      // Aquí estamos usando los datos de ejemplo (nombre, correo, password) como entrada
      // y rellenando los campos faltantes (apellidos, fecha_nacimiento, etc.).

      const userData = {
        nombre: nombre,
        apellido_p: apPaterno,
        apellido_m: apMaterno,
        correo: correo,
        contrasena: pass1,
        fecha_nacimiento: new Date(fechaNacimiento).toISOString(),
        // Datos del perfil - usando nombre como nombre de usuario y otros campos de 'perfilData' si existen
        nom_usuario: nombre.toLowerCase().replace(/\s+/g, ''),
        descripcion: initialUserData.descripcion || "",
        foto_perfil: initialUserData.imagen || ""
      };

      console.log("Enviando datos:", userData);

      const data = await registro(userData);

      console.log("Registro exitoso:", data);

      alert(`¡Bienvenido ${data.usuario.nombre}! Tu cuenta ha sido creada.`);
      navigate("/perfil");

    } catch (error) {
      console.error("Error en registro:", error);

      // Intentar parsear el error para mostrar mensaje específico
      let errorMsg = "Error al registrar usuario";
      try {
        const errorData = JSON.parse(error.message);
        if (errorData.correo) {
          errorMsg = "Este correo ya está registrado";
        } else if (errorData.nom_usuario) {
          errorMsg = "Este nombre de usuario ya está en uso";
        } else {
          errorMsg = JSON.stringify(errorData);
        }
      } catch {
        errorMsg = error.message;
      }

      alert(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Base_Main tituloPagina="Registro">
      <div className="registro-contenido">
        <form className="registro-forma" onSubmit={registrarUsuario}>
          <table>
            <tbody>
              <tr>
                <td>Nombre</td>
                <td>
                  <input
                    type="text"
                    value={nombre}
                    onChange={(e) => setNombre(e.target.value)}
                    required
                    disabled={loading}
                  />
                </td>
              </tr>
              <tr>
                <td>Apellido Paterno</td>
                <td>
                  <input
                    type="text"
                    value={apPaterno}
                    onChange={(e) => setApPaterno(e.target.value)}
                    required
                    disabled={loading}
                  />
                </td>
              </tr>
              <tr>
                <td>Apellido Materno</td>
                <td>
                  <input
                    type="text"
                    value={apMaterno}
                    onChange={(e) => setApMaterno(e.target.value)}
                    required
                    disabled={loading}
                  />
                </td>
              </tr>
              <tr>
                <td>Correo</td>
                <td>
                  <input
                    type="email"
                    value={correo}
                    onChange={(e) => setCorreo(e.target.value)}
                    required
                    disabled={loading}
                  />
                </td>
              </tr>
              <tr>
                <td>Fecha de Nacimiento</td>
                <td>
                  <input
                    type="date"
                    value={fechaNacimiento}
                    onChange={(e) => setFechaNacimiento(e.target.value)}
                    required
                    disabled={loading}
                    max={new Date().toISOString().split('T')[0]}
                  />
                </td>
              </tr>
              <tr>
                <td>Contraseña</td>
                <td>
                  <input
                    type="password"
                    value={pass1}
                    onChange={(e) => setPass1(e.target.value)}
                    required
                    disabled={loading}
                  />
                </td>
              </tr>
              <tr>
                <td>Repetir Contraseña</td>
                <td>
                  <input
                    type="password"
                    value={pass2}
                    onChange={(e) => setPass2(e.target.value)}
                    required
                    disabled={loading}
                  />
                </td>
              </tr>
            </tbody>
          </table>

          <button
          type="submit"
          className="registro-boton"
          disabled={loading}>
            {loading ? "Registrando..." : "Registrarse"}
          </button>

          <p className="registro-login">¿Ya tienes cuenta?</p>
          <a href="/cuenta">Iniciar sesión</a>
        </form>
      </div>
    </Base_Main>
  );
}
